package com.cenedu.backend.ai.problem.render; import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test;
class DeterministicLayoutTest { @Test void triesFixedOffsetsAndRejectsOccupiedViewport(){var l=new DeterministicLabelLayout();assertThat(l.place(100,100,300,200,20,10,List.of())).containsExactly(100,88);assertThatThrownBy(()->l.place(0,0,20,20,20,20,List.of())).isInstanceOf(DiagramRenderException.class);} @Test void clampsCoordinates(){assertThat(PlotClipper.clamp(11,0,10)).isEqualTo(10);assertThat(PlotClipper.inside(5,5,0,10,0,10)).isTrue();} }
